</code></pre> <pre><code>abstract class Animal(val nombre: String) {
    abstract fun hablar(): String
}

class Perro(nombre: String) : Animal(nombre) {
    override fun hablar() = "Guau guau"
}

class Gato(nombre: String) : Animal(nombre) {
    override fun hablar() = "Miau"
}
</code></pre> <pre><code>@Composable
fun FichaAnimal(animal: Animal) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(8.dp),
        elevation = CardDefaults.cardElevation()
    ) {
        Column(Modifier.padding(16.dp)) {
            Text("Animal: ${animal.nombre}")
            Text("Sonido: ${animal.hablar()}")
        }
    }
}
</code></pre> <pre><code>@Composable
fun ListaAnimales() {
    val animales: List&lt;Animal&gt; = listOf(
        Perro("Bobby"),
        Gato("Misu"),
        Perro("Toby")
    )

    LazyColumn {
        items(animales) { animal -&gt;
            FichaAnimal(animal)
        }
    }
}
</code></pre>

